#!/usr/bin/env node
'use strict';
/**
 * check-android-config — verify the generated Android project still matches
 * android-config/ and capacitor.config.json.
 *
 * mobile/android/ is gitignored and generated by `cap add android`, so it drifts
 * from the templates without warning — the same failure mode that sent an iOS
 * build to the wrong App Store Connect record. Google Play rejects a bad
 * applicationId, a stale targetSdk or a reused versionCode only at upload,
 * after a full signed build.
 *
 * Usage:
 *   node scripts/check-android-config.js          exit 1 on mismatch
 *   node scripts/check-android-config.js --warn   always exit 0, print loudly
 */

const fs     = require('fs');
const path   = require('path');
const blocks = require('./gradle-blocks');

/* Name of the innermost block enclosing `pos`, for the error message — knowing
   signingConfigs landed inside defaultConfig is what makes the fix obvious. */
function enclosingBlockName(src, pos, from) {
  const stack = [];
  const NAME = /([A-Za-z_$][\w$]*)\s*\{$/;
  for (let i = from; i < pos; i++) {
    if (src[i] === '{') {
      const m = NAME.exec(src.slice(Math.max(0, i - 60), i + 1));
      stack.push(m ? m[1] : null);
    } else if (src[i] === '}') stack.pop();
  }
  for (let i = stack.length - 1; i >= 0; i--) if (stack[i]) return stack[i];
  return null;
}

const WARN_ONLY = process.argv.includes('--warn');
const MOBILE    = path.resolve(__dirname, '..');
const TPL_VARS  = path.join(MOBILE, 'android-config', 'variables.gradle');
const TPL_STR   = path.join(MOBILE, 'android-config', 'app', 'src', 'main', 'res', 'values', 'strings.xml');
const PRJ_VARS  = path.join(MOBILE, 'android', 'variables.gradle');
const PRJ_GRADLE= path.join(MOBILE, 'android', 'app', 'build.gradle');
const PRJ_STR   = path.join(MOBILE, 'android', 'app', 'src', 'main', 'res', 'values', 'strings.xml');
const PRJ_GSVC  = path.join(MOBILE, 'android', 'app', 'google-services.json');
const CAPCONFIG = path.join(MOBILE, 'capacitor.config.json');

const problems = [];
const notes    = [];

/* Gradle uses two forms and both appear in this project:
     variables.gradle     minSdkVersion = 22          (assignment)
     app/build.gradle     applicationId "co.za..."    (method call, no '=')
   The '=' is therefore optional. Getting this wrong made applicationId read as
   unset, so a wrong Play listing passed the check silently. */
const gradleVal = (text, key) => {
  const m = text && text.match(new RegExp(`\\b${key}\\s*=?\\s*['"]?([^'"\\s]+)['"]?`));
  return m ? m[1] : null;
};
const xmlVal = (text, name) => {
  const m = text && text.match(new RegExp(`<string name="${name}"\\s*>([^<]*)</string>`));
  return m ? m[1].trim() : null;
};
const rel = p => {
  const r = path.relative(process.cwd(), p);
  return r && !r.startsWith('..') ? r : p;
};

function main() {
  if (!fs.existsSync(TPL_VARS)) {
    console.error(`[check:android] template missing: ${rel(TPL_VARS)}`);
    return 1;
  }
  if (!fs.existsSync(PRJ_VARS) && !fs.existsSync(PRJ_GRADLE)) {
    console.log('[check:android] mobile/android/ not generated yet — nothing to check.');
    console.log('[check:android] run `npm run add:android`, then copy android-config/ in (see README).');
    return 0;
  }

  const tplVars = fs.readFileSync(TPL_VARS, 'utf8');
  const prjVars = fs.existsSync(PRJ_VARS) ? fs.readFileSync(PRJ_VARS, 'utf8') : null;
  const gradle  = fs.existsSync(PRJ_GRADLE) ? fs.readFileSync(PRJ_GRADLE, 'utf8') : null;

  /* SDK levels. targetSdk is the one with a Google Play deadline attached — Play
     stops accepting updates built against an older target after its cutoff. */
  for (const key of ['minSdkVersion', 'compileSdkVersion', 'targetSdkVersion']) {
    const want = gradleVal(tplVars, key);
    const got  = prjVars ? gradleVal(prjVars, key) : null;
    if (want == null) continue;
    if (got == null) {
      problems.push(`${key} not found in android/variables.gradle — expected ${want}`);
    } else if (got !== want) {
      problems.push(`${key} is ${got} — expected ${want}`
        + (key === 'targetSdkVersion' ? '  (Google Play enforces this at upload)' : ''));
    }
  }

  /* applicationId decides which Play listing a build belongs to — the Android
     equivalent of the bundle identifier that misrouted an iOS upload. */
  let wantId = null;
  try { wantId = JSON.parse(fs.readFileSync(CAPCONFIG, 'utf8')).appId || null; } catch (_) {
    notes.push('capacitor.config.json could not be parsed');
  }
  const gotId = gradle ? gradleVal(gradle, 'applicationId') : null;
  if (wantId && gotId && gotId !== wantId) {
    problems.push(`applicationId is "${gotId}" — expected "${wantId}"  (decides the Play listing)`);
  } else if (wantId && !gotId) {
    notes.push('applicationId not found in android/app/build.gradle');
  }

  /* strings.xml package_name is used by the Capacitor bridge and deep links. */
  if (fs.existsSync(PRJ_STR) && fs.existsSync(TPL_STR)) {
    const w = xmlVal(fs.readFileSync(TPL_STR, 'utf8'), 'package_name');
    const g = xmlVal(fs.readFileSync(PRJ_STR, 'utf8'), 'package_name');
    if (w && g && w !== g) problems.push(`strings.xml package_name is "${g}" — expected "${w}"`);
  }

  /* Reported, not judged: Play requires versionCode to strictly increase, and
     only Play knows what has already been used. */
  const versionCode = gradle ? gradleVal(gradle, 'versionCode') : null;
  const versionName = gradle ? gradleVal(gradle, 'versionName') : null;

  if (!fs.existsSync(PRJ_GSVC)) {
    notes.push('google-services.json missing from android/app/ — push notifications will not work');
  }

  /* Release signing. A misplaced signingConfigs block still works — Groovy
     closures resolve owner-first, so a call nested one level too deep falls
     through to the android extension anyway — but nothing reports it, and the
     next person to move code around loses signing silently.

     This is checked by brace depth, not by looking for a closing brace between
     aaptOptions and signingConfigs: that heuristic passes the exact case it
     was written to catch, because aaptOptions *does* close. The block still
     open is defaultConfig. */
  if (gradle) {
    const android = blocks.findAndroidBlock(gradle);
    if (!android) {
      problems.push('could not find the `android { }` block in android/app/build.gradle');
    } else {
      const direct = blocks.findChildBlock(gradle, 'signingConfigs', android.open, android.end);
      const any    = blocks.findAnyBlock(gradle, 'signingConfigs', android.open, android.end);

      if (!any) {
        problems.push('no signingConfigs block in android/app/build.gradle — see android-config/signing-config.gradle.patch');
      } else if (!direct) {
        const inside = enclosingBlockName(gradle, any.open, android.open);
        problems.push(
          `signingConfigs is nested ${any.depth} level${any.depth === 1 ? '' : 's'} too deep` +
          (inside ? ` (inside ${inside})` : '') +
          ' — it belongs directly inside android { }. Groovy resolves owner-first so it still ' +
          'works today, which is why nothing has complained. Run `npm run apply:android` to move it.');
      }

      // The line that actually decides whether the AAB is signed.
      const bt  = blocks.findChildBlock(gradle, 'buildTypes', android.open, android.end);
      const rel = bt && blocks.findChildBlock(gradle, 'release', bt.open, bt.end);
      if (!rel) {
        problems.push('could not find buildTypes.release in android/app/build.gradle');
      } else if (!/signingConfig\s+signingConfigs\.release/.test(gradle.slice(rel.open, rel.end))) {
        problems.push('release buildType does not set signingConfig signingConfigs.release — the release AAB will be unsigned and Play will reject it');
      }
    }
  }

  const show = v => (v == null ? '(unset)' : String(v));
  console.log('[check:android] Android project vs android-config');
  for (const key of ['minSdkVersion', 'compileSdkVersion', 'targetSdkVersion']) {
    console.log(`                ${key.padEnd(18)} ${show(prjVars && gradleVal(prjVars, key)).padEnd(10)} expected ${show(gradleVal(tplVars, key))}`);
  }
  console.log(`                ${'applicationId'.padEnd(18)} ${show(gotId).padEnd(10)} expected ${show(wantId)}`);
  console.log(`                ${'versionCode'.padEnd(18)} ${show(versionCode)}   ${'versionName'} ${show(versionName)}`);

  for (const n of notes) console.log(`[check:android] note: ${n}`);

  if (!problems.length) {
    console.log('[check:android] OK — project matches android-config.');
    console.log('[check:android] Not checked (Google Play only knows this):');
    console.log('[check:android]   · versionCode must be higher than any already uploaded');
    return 0;
  }

  console.error('');
  for (const p of problems) console.error(`[check:android] MISMATCH: ${p}`);
  console.error('');
  console.error('[check:android] Copy the templates in, from an up-to-date checkout:');
  console.error(`[check:android]   cp "${rel(TPL_VARS)}" "${rel(PRJ_VARS)}"`);
  console.error('[check:android] applicationId is set in android/app/build.gradle.');
  return 1;
}

const code = main();
process.exit(WARN_ONLY ? 0 : code);
